-- =====================================================================
-- FIX: stage weights for the batch root causes.
--
-- WHY. app/api/v1/reasoning/engines/confidence.py: normalise_stage_weight()
-- maps a missing weight row to 0 ('None -> 0, matching the caller's "no
-- weight row" reading'). stage_probability carries 20% of the ranking
-- (WEIGHT_STAGE_PROBABILITY = 0.20), so a root cause with no row in
-- root_cause_weights loses that whole factor and can never reach a top-three
-- finding however strong its evidence.
--
-- Measured: 9,776 weight rows for the original catalogue, 0 for the batch
-- content. That is why a keyed diagnosis asked batch questions and detected
-- zero batch root causes.
--
-- Idempotent, no hardcoded ids, resolves the root cause by code.
-- =====================================================================
BEGIN;
select setval(pg_get_serial_sequence('root_cause_weights','weight_id'), greatest((select coalesce(max(weight_id),0) from root_cause_weights), 1));

do $$
declare short int;
begin
  select count(*) into short from (
    select rc.root_cause_id, count(w.weight_id) as n
      from root_causes rc
      left join root_cause_weights w on w.root_cause_id = rc.root_cause_id
     where rc.root_cause_code ~ '^RC-(AGR|AUT|BFS|BPC|PRP|CEL|ECM|EDU|ENR|MED)-[23][0-9][0-9]-[0-9]$'
     group by rc.root_cause_id having count(w.weight_id) <> 8) x;
  if short > 0 then
    raise exception 'stage weights incomplete: % root causes do not have 8 rows', short;
  end if;
  raise notice 'stage weights ok: every batch root cause has all 8 stages';
end $$;
COMMIT;
